import {
  ColumnChooser,
  Grid,
  Table,
  TableColumnVisibility,
  TableHeaderRow,
  Toolbar,
} from '@devexpress/dx-react-grid-material-ui';
import React, { Component } from 'react';
import { FormattedMessage } from 'react-intl';
import Pagination2 from 'react-js-pagination';
import Loader from 'react-loader-spinner';
import { connect } from 'react-redux';
import { Alert, Button, Card, CardBody, CardGroup, CardHeader, Col, Row } from 'reactstrap';
import { bindActionCreators } from 'redux';

import { downloadT461Transactions, fetchT461Transactions } from '../../../../actions/filesets';
import Widget04 from '../../../../Utils/Widgets04';

// import {fetchFileSetsDefinitionBatchesTransactionsPaginated,fetchFileSetBatchDetail,fetchFileSetsDefinitionBatchesDetail} from '../../actions/filesets';

// import AddFileSet from './addFileSet';
// import UpdateFileSet from './updateFileSet';

class MastercardT461Transactions extends Component {
    constructor(props){
        super(props);
        this.state ={
            modal:false,
            showUpdateModal:false,
            fileSetCreatedAlert:true,
            filesetUpdatedAlert:true,
            fileSetDeletedAlert:true,
            fileSetT461TransactionError:true,
            deleteModal:false,
            activePage:1,
            defaultHiddenColumnNames: ['sex', 'car'],
        }
    }
    id=''
    fileDefinitionId = ''
  componentWillMount(){
      this.props.fetchT461Transactions(this.props.match.params.fileId,0);
  }
  componentDidUpdate(prevProps,state){
    const { fileSets } = this.props;
    const { selectedAffiliateCode } = fileSets;
    if(prevProps.fileSets.selectedAffiliateCode !== selectedAffiliateCode){
      this.props.fetchT461Transactions(this.props.match.params.fileId,0);
    }
  }
  onSubmit = (values) => {
    this.props.createFileSet(values);
    this.setState({
        modal:false
    })
  }

  onSubmitUpdate = (values) => {
    this.props.updateFileSet(this.id,values);
    this.closeUpdateModal();
  }

  setUpProduct = (id) => {
      this.props.history.push(`/processors/${id}/subgroups/addProduct`);
  }
  
  toggle = () => {
    this.props.history.push(`/filesets/${this.props.match.params.id}/definitions/add`)
  }
  closeModal = () => {
    this.setState({ modal:false});
  }
  componentWillUnmount(){   
    // this.props.subGroupCreated.subGroupCreated = null;
    // this.props.subGroupCreated.createSubGroupError = null;
    // this.props.subGroupCreated.updatedSubGroup = null;
    
  }

  updateSubGroup = (id) =>{
    this.clearNotifications();
    this.setState({ showUpdateModal: !this.state.showUpdateModal });
    this.id = id;
    this.props.fetchFileSet(id);
  }

  closeUpdateModal = () => {
    
    this.setState({ showUpdateModal: !this.state.showUpdateModal });
  }

  toggleUpdate = () => {
   
    this.setState({ showUpdateModal: !this.state.showUpdateModal });
  }

  clearNotifications=()=>{
    this.props.fileSets.fileSetCreated= null;
    // this.props.subGroupCreated.createSubGroupError = null;
    // this.props.subGroupCreated.subGroupCreated = null;

  }

  onDismissFileSetCreatedSuccessAlert = () =>{
      this.setState({
        fileSetCreatedAlert:false
      })
  }

  onDismissFileSetUpdatedSuccessAlert = () => {
      this.setState({
          fileSetUpdatedAlert: false
      })
  }

  deleteFileDefinition = (id) => {
    this.clearNotifications()
    this.setState({deleteModal:true});
    this.fileDefinitionId = id;
  }

  toggleConfirm = () =>{
    this.setState({ deleteModal: !this.state.deleteModal });
}
confirm = ()=> {
  this.props.deleteFileSetDefinition(this.props.match.params.id,this.fileDefinitionId);
  this.setState({deleteModal:false});
}

onDismissFileSetDeletedSuccessAlert = () => {
  this.setState({
    fileSetDeletedAlert:false
  })
}

handlePageChange = (pageNumber) => {
  let pageNumberParam = pageNumber - 1;
  
  this.props.fetchT461Transactions(this.props.match.params.fileId,pageNumberParam);
  this.setState({activePage: pageNumber});

  
}

onSubmit = (values) => {
  this.props.fetchFileSetsDefinitionBatchesTransactionsPaginated(this.props.match.params.filesetId,this.props.match.params.batchesId,this.props.match.params.definitionId,0,values.affiliate.value);
  

}

onDismissFileSetT461ErrorAlert = () => {
  this.setState({
    fileSetT461TransactionError:false
  })
}

downloadTransactions = (fileId) => {
  this.props.downloadT461Transactions(fileId);
}




  render() {
    const { fileSets } = this.props;
    const {t461Transactions,t461TransactionsLoading,t461TransactionsError } = fileSets;
    if(t461Transactions){
      if(t461Transactions.data.content.length > 0){
          delete t461Transactions.data.content[0].t461;
          delete t461Transactions.data.content[0].id;
          var columnHeaders = t461Transactions.data.content[0];
          var newRows = [];
          for(var name in columnHeaders){
              var newObj = {};
              newObj.name = name;
              newObj.title = name;
              newRows.push(newObj);
          }
          var payloadArray = [];
          t461Transactions.data.content.forEach(function(item){
              if(item.t461){
                  delete item.t461;
                  delete item.id;
              }
              payloadArray.push(item);
              
          })
          console.log('PayloadArray is ',payloadArray);
      }
  }
    const { defaultHiddenColumnNames } = this.state;
    
    console.log('Props is ',this.props);
    return (
      <div className="animated fadeIn">
        {/* <Row>
            <Col style={{ 'textAlign': 'right' }}>
            <Button style={{ 'marginBottom': '20px' }} color="success" onClick={this.toggle}>
            <i className="fa fa-plus"></i>&nbsp;<FormattedMessage id="Add FileSet" defaultMessage="Add FileSet"/></Button>
            </Col>
        </Row> */}
        <Row>
          <Col>
          {t461Transactions?<CardGroup className="mb-4">
            <Widget04 icon="icon-people" color="info" header={t461Transactions.data.meta.totalElements.toLocaleString()} value="25">Transactions</Widget04>
            <Widget04 icon="icon-user-follow" color="success" header="0" value="25">Successful Transactions</Widget04>
            <Widget04 icon="icon-basket-loaded" color="warning" header="0" value="25">Credits</Widget04>
            <Widget04 icon="icon-pie-chart" color="primary" header="0" value="5">Debits</Widget04>
            <Widget04 icon="icon-speedometer" color="danger" header="0" value="25">Amount</Widget04>
          </CardGroup>:
           <Row>
           <article className='mx-auto'>
             <div>
               <Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
             </div>
           </article>
         </Row>
          }
        
          </Col>
        </Row>
        <Row>
        
            {/* <Col xs="12">
                <SearchBatchesFormComponent {...this.props} onSubmit = {this.onSubmit} {...this.state} change={this.change}/>
            </Col> */}

          
          <Col lg={12}>
           {this.props.fileSets.fileSetFileDefinitionDeleted?<Alert color="success" isOpen={this.state.fileSetDeletedAlert} toggle={this.onDismissFileSetDeletedSuccessAlert}>
                    
                    <FormattedMessage id="Success: FileSet Deleted Succesfully!" defaultMessage="Success: FileSet Deleted Succesfully!"/>
                    </Alert>:null}
        
             {t461TransactionsError?<Alert color="danger" isOpen={this.state.fileSetT461TransactionError} toggle={this.onDismissFileSetT461ErrorAlert}>
                    {t461TransactionsError.data.message}
            </Alert>:null} 
            <Card>
              <CardHeader>
                
              <strong> {t461Transactions ? <React.Fragment> 
                Mastercard T461 {this.props.match.params.fileId}
                </React.Fragment> : ""}<FormattedMessage id=" Transactions" defaultMessage=" Transactions"/></strong>
                
                {t461Transactions?[
                  t461Transactions.data.content.length > 0 ? 
                  // <a href="" onClick={e => this.downloadTransactions(this.props.match.params.date)} href="javascript:;" download={""+1+".csv"}><i class="fa fa-download" aria-hidden="true" ></i></a>
                  <Button className={'float-right mb-0 btn-sm'} color="success" onClick={e => this.downloadTransactions(this.props.match.params.fileId)}><i className="fa fa-download"></i>&nbsp; <FormattedMessage id="Download CSV" defaultMessage="Download CSV" /></Button>
                  :''
                ]:[
                  ''
                ]
                }
              </CardHeader>
              <CardBody>
              {t461TransactionsLoading && (
									<Row>
										<article className='mx-auto'>
											<div>
												<Loader type='ThreeDots' color='#00BFFF' height={100} width={100} />
											</div>
										</article>
									</Row>
								)}
              {   this.props.fileSets.t461Transactions
                                    ? [
                                        this.props.fileSets.t461Transactions.data.content.length > 0 ?  this.props.fileSets.t461Transactions ? 
                                      <Grid
                                      rows={payloadArray}
                                      columns={newRows}
                                      >
                                      <Table />
                                      <TableHeaderRow />
                                      <TableColumnVisibility
                                          defaultHiddenColumnNames={defaultHiddenColumnNames}
                                      />
                                      <Toolbar />
                                      <ColumnChooser />
                                      </Grid>
                                      
                                        :<p className="text-center text-danger"><FormattedMessage id="There are no batch transactions at the moment." defaultMessage="There are no batch transactions at the moment."/></p>:<p className="text-center text-danger"><FormattedMessage id="There are no batch transactions at the moment." defaultMessage="There are no batch transactions at the moment."/></p>
                                    ]
                                    : [
                                        ''
                                    ]
                                }
                {this.props.fileSets.t461Transactions?<nav>
                    <Pagination2
                        activePage={this.state.activePage}
                        itemsCountPerPage={20}
                        totalItemsCount={this.props.fileSets.t461Transactions?this.props.fileSets.t461Transactions.data.meta.totalElements:null}
                        pageRangeDisplayed={5} 
                        onChange={this.handlePageChange}
                    />
                    </nav>:'' }
              </CardBody>
            </Card>
          </Col>
        </Row>
      </div>
    )
  }
}

const mapStateToProps = (state) => {
  console.log('State is ',state);
  return {
    fileSets:state.fileSets,
    utils:state.utils

  }
}

const mapDispatchToProps= (dispatch) => {
  return bindActionCreators({
    fetchT461Transactions,
    downloadT461Transactions
  },dispatch)
}

export default connect(mapStateToProps,mapDispatchToProps)(MastercardT461Transactions);

